/** Derive one visible activation interval from ordered call and return messages. */
export function SequenceActivation({ bottom, edges, node }: SequenceActivationProps) {
    const call = edges.find(({ kind, to }) => to === node.id && (kind === 'call' || kind === 'success'))
    if (!call) return null
    const start = edgeRow(call)
